import pyomo.environ as pyo

DATA = {
    "aircraft": ["aircraft_0", "aircraft_1", "aircraft_2", "aircraft_3"],
    "earliest": {
        "aircraft_0": 0,
        "aircraft_1": 7,
        "aircraft_2": 225,
        "aircraft_3": 119,
    },
    "latest": {
        "aircraft_0": 37,
        "aircraft_1": 67,
        "aircraft_2": 285,
        "aircraft_3": 179,
    },
    "early_pen": {
        "aircraft_0": 61,
        "aircraft_1": 35,
        "aircraft_2": 74,
        "aircraft_3": 93,
    },
    "late_pen": {
        "aircraft_0": 82,
        "aircraft_1": 34,
        "aircraft_2": 41,
        "aircraft_3": 56,
    },
    # Required separation (setup) if i lands after j
    # and if j lands after i, in minutes.
    "sep_ij": {
        ("aircraft_0", "aircraft_1"): 30,
        ("aircraft_0", "aircraft_2"): 30,
        ("aircraft_0", "aircraft_3"): 30,
        ("aircraft_1", "aircraft_2"): 30,
        ("aircraft_1", "aircraft_3"): 30,
        ("aircraft_2", "aircraft_3"): 30,
    },
    "big_M": 1000,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    aircraft = d["aircraft"]
    pairs = list(d["sep_ij"].keys())

    model = pyo.ConcreteModel()

    model.A = pyo.Set(initialize=aircraft)

    def _make_pairs(m):
        return pairs

    model.P = pyo.Set(initialize=[
        (i, j) for (i, j) in pairs if aircraft.index(i) < aircraft.index(j)
    ])

    def t_lb(m, i):
        return d["earliest"][i]

    def t_ub(m, i):
        return d["latest"][i]

    model.t = pyo.Var(
        model.A,
        bounds=lambda m, i: (d["earliest"][i], d["latest"][i]),
        within=pyo.NonNegativeReals,
    )
    model.early = pyo.Var(model.A, within=pyo.NonNegativeReals)
    model.late = pyo.Var(model.A, within=pyo.NonNegativeReals)
    model.y = pyo.Var(model.P, within=pyo.Binary)

    def rule_dev_balance(m, i):
        return m.t[i] - m.late[i] + m.early[i] == d["earliest"][i]

    model.dev_balance = pyo.Constraint(model.A, rule=rule_dev_balance)

    def rule_sep_ij(m, i, j):
        # if y[i,j] == 1 -> i before j: t[j] >= t[i] + sep
        sep = d["sep_ij"].get((j, i)) or d["sep_ij"].get((i, j))
        return m.t[j] - m.t[i] >= sep - d["big_M"] * (1 - m.y[i, j])

    model.sep_ij = pyo.Constraint(model.P, rule=rule_sep_ij)

    def rule_sep_ji(m, i, j):
        sep = d["sep_ij"].get((i, j)) or d["sep_ij"].get((j, i))
        return m.t[i] - m.t[j] >= sep - d["big_M"] * m.y[i, j]

    model.sep_ji = pyo.Constraint(model.P, rule=rule_sep_ji)

    def rule_obj(m):
        return sum(
            d["early_pen"][i] * m.early[i] + d["late_pen"][i] * m.late[i]
            for i in aircraft
        )

    model.obj = pyo.Objective(rule=rule_obj, sense=pyo.minimize)

    return model
